package example;

import java.time.Duration;
import java.util.List;
import java.util.concurrent.StructuredTaskScope;
import java.util.concurrent.StructuredTaskScope.Joiner;
import java.util.concurrent.StructuredTaskScope.Subtask;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Stream;

record Widget(String source, boolean authoritative) {}
interface WidgetClient {
    Widget primary() throws Exception;
    Widget fallback() throws Exception;
}
final class Dashboard {
    static List<Widget> load(WidgetClient client, AtomicLong timeoutCount)
            throws InterruptedException {
        try (var scope = StructuredTaskScope.open(
                Joiner.<Widget>allUntil(task ->
                        task.state() == Subtask.State.SUCCESS
                                && task.get().authoritative()),
                config -> config.withTimeout(Duration.ofMillis(200)))) {
            scope.fork(client::primary);
            scope.fork(client::fallback);
            try {
                Stream<Subtask<Widget>> completed = scope.join();
                return completed
                        .filter(task -> task.state() == Subtask.State.SUCCESS)
                        .map(Subtask::get)
                        .toList();
            } catch (StructuredTaskScope.TimeoutException timedOut) {
                timeoutCount.incrementAndGet();
                return List.of();
            }
        }
    }
}
